1946	fn bare_clause_guard<'a>(
1947	    guard: &'a TypedClauseGuard,
1948	    env: &mut Env<'a>,
1949	    assignments: &HashMap<EcoString, &StringPatternAssignment<'a>>,
1950	) -> Document<'a> {
1951	    match guard {
1952	        ClauseGuard::Block { value, .. } => {
1953	            bare_clause_guard(value, env, assignments).surround("(", ")")
1954	        }
1955	
1956	        ClauseGuard::Not { expression, .. } => {
1957	            docvec!["not ", bare_clause_guard(expression, env, assignments)]
1958	        }
1959	
1960	        ClauseGuard::BinaryOperator {
1961	            operator,
1962	            left,
1963	            right,
1964	            ..
1965	        } => {
1966	            let left_document = clause_guard(left, env, assignments);
1967	            let right_document = clause_guard(right, env, assignments);
1968	
1969	            let operator = match operator {
1970	                BinOp::Or => "orelse",
1971	                BinOp::And => "andalso",
1972	                BinOp::Eq => "=:=",
1973	                BinOp::NotEq => "=/=",
1974	                BinOp::GtInt | BinOp::GtFloat => ">",
1975	                BinOp::GtEqInt | BinOp::GtEqFloat => ">=",
1976	                BinOp::LtInt | BinOp::LtFloat => "<",
1977	                BinOp::LtEqInt | BinOp::LtEqFloat => "=<",
1978	                BinOp::AddInt | BinOp::AddFloat => "+",
1979	                BinOp::SubInt | BinOp::SubFloat => "-",
1980	                BinOp::MultInt | BinOp::MultFloat => "*",
1981	                BinOp::DivFloat => "/",
1982	                BinOp::DivInt => "div",
1983	                BinOp::RemainderInt => "rem",
1984	                BinOp::Concatenate => {
1985	                    return clause_guard_string_concatenate(left, right, env, assignments);
1986	                }
1987	            };
1988	
1989	            docvec![left_document, " ", operator, " ", right_document]
1990	        }
1991	
1992	        // Only local variables are supported and the typer ensures that all
1993	        // ClauseGuard::Vars are local variables
1994	        ClauseGuard::Var { name, .. } => {
1995	            // If we're referencing a variable introduced by a string pattern
1996	            // assignment we need to replace it with its actual literal value:
1997	            // in the generated code the variable is only defined later, so
1998	            // just referencing its name would result in an error.
1999	            assignments
2000	                .get(name)
2001	                .map(|assignment| assignment.literal_value.clone())
2002	                .unwrap_or_else(|| env.local_var_name(name))
2003	        }
2004	
2005	        ClauseGuard::TupleIndex { tuple, index, .. } => tuple_index_inline(tuple, *index, env),
2006	
2007	        ClauseGuard::FieldAccess {
2008	            container, index, ..
2009	        } => tuple_index_inline(container, index.expect("Unable to find index") + 1, env),
2010	
2011	        ClauseGuard::ModuleSelect { literal, .. } => const_inline(literal, env),
2012	
2013	        ClauseGuard::Constant(constant) => const_inline(constant, env),
2014	    }
2015	}
